import {reports,scope3Breakdown,metricLabels,yearChange,reportScenario,reportIndex} from './reports-data.mjs';
const n=(v,d=2)=>v===null?'—':new Intl.NumberFormat('id-ID',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source=(r,page=r.page,pdf=r.pdfPage,label)=>`<a class="source-link" href="${r.url}#page=${pdf}" target="_blank" rel="noopener noreferrer">${label??`Laporan ${r.year} · hlm. ${page}`} ↗</a>`;
const change=v=>v===null?'Tidak ada pembanding':`${v<0?'−':'+'}${n(Math.abs(v),1)}% dibanding tahun sebelumnya`;
const current=s=>reports.find(r=>r.year===s.reportYear)??reports.at(-1);
function head(state,title,sub){return `<div class="report-head"><div><p class="report-kicker">PT UNILEVER INDONESIA TBK · 2021—2025</p><h1>${title}</h1><p>${sub}</p></div><button class="btn report-export" data-report-action="export">Unduh data CSV <span aria-hidden="true">↓</span></button></div><div class="report-toolbar"><div class="year-switch" role="group" aria-label="Pilih tahun laporan">${reports.map(r=>`<button data-report-year="${r.year}" class="${r.year===state.reportYear?'selected':''}" aria-pressed="${r.year===state.reportYear}">${r.year}</button>`).join('')}</div><span class="report-source-tag">Sumber: sustainability report resmi</span></div>`;}
function chart(state,key='operational'){
 const width=780,height=290,left=65,right=60,top=45,bottom=45,values=reports.map(r=>r[key]),max=Math.max(...values.filter(v=>v!==null),1)*1.12;
 const x=i=>left+i*(width-left-right)/4,y=v=>height-bottom-v/max*(height-top-bottom),unit=key==='intensity'?'kg CO₂e / ton produk':'t CO₂e';
 let path='',started=false;values.forEach((v,i)=>{if(v===null){started=false;return;}path+=`${started?'L':'M'}${x(i)},${y(v)} `;started=true;});
 const description=reports.map(r=>`${r.year}: ${r[key]===null?'tidak tersedia':n(r[key])}`).join('; ');
 return `<div class="report-chart-title"><div><h2>${metricLabels[key]}</h2><p>${unit} · angka sebagaimana dilaporkan</p></div><span class="chart-key"><i></i> Unilever Indonesia</span></div><svg class="report-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${metricLabels[key]}, ${unit}. ${description}">${[0,.5,1].map(t=>`<line x1="${left}" y1="${y(max*t)}" x2="${width-right}" y2="${y(max*t)}" class="chart-grid"/><text x="${left-12}" y="${y(max*t)+4}" text-anchor="end" class="axis-text">${max>100000?n(max*t/1000000,1)+'jt':max>1000?n(max*t/1000,0)+'rb':n(max*t,0)}</text>`).join('')}<path d="${path}" class="report-line"/>${reports.map((r,i)=>`<text x="${x(i)}" y="${height-13}" text-anchor="middle" class="axis-text">${r.year}</text>${r[key]!==null?`<circle cx="${x(i)}" cy="${y(r[key])}" r="${r.year===state.reportYear?7:4}" class="report-point ${r.year===state.reportYear?'chosen':''}"/><text x="${x(i)}" y="${y(r[key])-18}" text-anchor="middle" class="point-value">${n(r[key],key==='intensity'?2:0)}</text>`:`<text x="${x(i)}" y="${y(0)-12}" text-anchor="middle" class="missing-value">Tidak tersedia</text>`}`).join('')}</svg><p class="chart-footnote">${key==='scope3'?'Hanya 2021 memiliki angka Scope 3 pada dataset ini. Tahun tanpa angka tidak diberi nilai nol atau dihubungkan dengan garis.':key==='intensity'?'Batas: aktivitas manufaktur saja; tidak termasuk logistik dan kantor. Angka tidak dipakai untuk menurunkan volume produksi organisasi.':'Batas organisasi dapat berubah. Perbandingan 2025 dipengaruhi perubahan cakupan gudang dan periode pelaporan es krim.'}</p>`;
}
function metrics(r){return `<dl class="report-metrics"><div><dt>Scope 1</dt><dd>${n(r.scope1)}</dd><small>t CO₂e · emisi langsung</small></div><div><dt>Scope 2</dt><dd>—<sup>1</sup></dd><small>Tanda “–” di tabel utama</small></div><div><dt>Scope 3</dt><dd class="${r.scope3===null?'text-metric':''}">${r.scope3===null?'Tidak tersedia':n(r.scope3,0)}</dd><small>${r.scope3===null?'Lihat status pengungkapan':'t CO₂e · data historis 2021'}</small></div><div><dt>Intensitas manufaktur</dt><dd>${n(r.intensity)}</dd><small>kg CO₂e / ton produk</small></div></dl>`;}
function overview(state){const r=current(state),delta=yearChange(r.year,'operational');return head(state,'Emisi operasional','Lima tahun pelaporan. Angka resmi, batas yang terlihat, dan keputusan yang bisa ditelusuri.')+`<div class="report-lead"><div><span class="report-kicker">SCOPE 1 + 2 · SUBTOTAL DILAPORKAN ${r.year}</span><div class="reported-total">${n(r.operational)} <span>t CO₂e</span></div><p class="reported-change">${change(delta)} <span>· belum dinormalisasi</span></p></div><div class="report-lead-note"><p>Subtotal operasional, bukan total jejak karbon seluruh rantai nilai.</p>${source(r,r.year===2025?186:r.page,r.year===2025?188:r.pdfPage)}</div></div>${metrics(r)}<div class="report-main-grid"><section class="trend-panel">${chart(state)}</section><aside class="evidence-aside"><span class="section-label">CATATAN TAHUN ${r.year}</span><h2>${r.year===2025?'Batas pelaporan berubah':'Baca angka bersama batasnya'}</h2><p>${e(r.boundary)}</p><p>${e(r.caveat)}</p>${source(r,r.year===2025?185:r.page,r.year===2025?187:r.pdfPage)}<a class="report-inline" href="#insights">Lihat temuan & risiko →</a></aside></div><div class="report-notes"><p><sup>1</sup> ${e(r.scope2Note)} Nilai kosong tidak diperlakukan sebagai nol.</p><p><strong>Scope 3.</strong> ${e(r.scope3Note)}</p></div><section class="report-bottom"><div><span class="section-label">DARI DATA KE TINDAKAN</span><h2>Panas proses, refrigeran, lalu kelengkapan rantai nilai.</h2></div><p>Evaluasi sumber emisi yang masih tercatat, pantau sumber yang meningkat, dan bangun kembali seri Scope 3. Prioritas ini adalah usulan analisis, bukan rencana resmi perusahaan. <a href="#plan">Buka prioritas tindakan →</a></p></section>`;}
function table(){return `<div class="table-wrap report-table"><table><caption>Seri emisi yang diekstrak dari laporan resmi</caption><thead><tr><th>Tahun</th><th class="num">Scope 1</th><th class="num">Scope 2¹</th><th class="num">Scope 3</th><th class="num">Scope 1 + 2²</th><th class="num">Intensitas³</th><th>Sumber</th></tr></thead><tbody>${reports.map(r=>`<tr><th scope="row">${r.year}</th><td class="num">${n(r.scope1)}</td><td class="num">—</td><td class="num">${r.scope3===null?'<span class="missing-cell">Tidak tersedia</span>':n(r.scope3,0)}</td><td class="num">${n(r.operational)}</td><td class="num">${n(r.intensity)}</td><td>${source(r)}</td></tr>`).join('')}</tbody></table></div><p class="chart-footnote">Emisi dalam t CO₂e. ¹ Tanda pada tabel utama, bukan nol yang diasumsikan. ² Subtotal dilaporkan, tidak dihitung dengan mengisi Scope 2 kosong. ³ kg CO₂e per ton produk, manufaktur saja.</p>`;}
function componentBars(r){return `<div class="report-chart-title"><div><h2>Komposisi Scope 1 · ${r.year}</h2><p>t CO₂e · dua komponen dilaporkan</p></div></div><div class="component-bars">${[['Gas & light fuel',r.fuel,'fuel'],['Refrigeran',r.refrigerants,'leaks']].map(([label,v,cls])=>`<div><div class="component-label"><span>${label}</span><strong>${n(v)} <small>${n(v/r.scope1*100,1)}%</small></strong></div><div class="component-track"><span class="${cls}" style="width:${v/r.scope1*100}%"></span></div></div>`).join('')}</div><p class="chart-footnote">${source(r,r.detailPage??r.page,r.detailPdf??r.pdfPage)}. Tidak tersedia rincian alokasi emisi per pabrik dalam dataset ini.</p>`;}
function analytics(state){const r=current(state);return head(state,'Analisis lima tahun','Pilih indikator untuk melihat perubahan, komposisi, dan celah pengungkapan.')+`<div class="analysis-controls"><label>Indikator tren<select id="report-metric">${['operational','scope1','scope3','refrigerants','intensity'].map(k=>`<option value="${k}" ${state.reportMetric===k?'selected':''}>${metricLabels[k]}</option>`).join('')}</select></label><p>Perubahan angka merupakan perbandingan pelaporan, bukan estimasi dampak satu program.</p></div><section class="report-wide-chart">${chart(state,state.reportMetric)}</section><div class="report-split"><section>${componentBars(r)}</section><section><div class="report-chart-title"><div><h2>Rantai nilai · data 2021</h2><p>${r.year===2021?'Rincian yang dilaporkan pada 2021':'Scope 3 historis, bukan estimasi '+r.year}</p></div></div><div class="historical-bars">${scope3Breakdown.map(v=>`<div><span>${v.label}</span><div class="component-track"><span style="width:${v.value/scope3Breakdown[0].value*100}%"></span></div><strong>${n(v.value,0)}</strong></div>`).join('')}</div><p class="chart-footnote">t CO₂e · ${source(reports[0])}. Pengelompokan mengikuti laporan, tidak diklaim mewakili seluruh 15 kategori GHG Protocol.</p></section></div>${table()}`;}
function insights(state){const r=current(state),prev=reports.find(v=>v.year===r.year-1),leaks=yearChange(r.year,'refrigerants');return head(state,'Temuan & batas interpretasi','Apa yang berubah, apa artinya bagi keputusan, dan apa yang belum dapat disimpulkan.')+`<div class="insight-ledger"><article><span>01</span><div><h2>Emisi operasional ${prev?(r.operational<prev.operational?'turun':'naik'):'menjadi titik awal seri'}</h2><p class="finding-number">${n(r.operational)} <small>t CO₂e · ${r.year}</small></p><p>${prev?`${change(yearChange(r.year,'operational'))}. `:''}${e(r.caveat)}</p><p><strong>Implikasi.</strong> Pisahkan pengaruh produksi, perubahan portofolio, faktor emisi dan efisiensi sebelum menetapkan keberhasilan program.</p>${source(r)}</div></article><article><span>02</span><div><h2>Refrigeran perlu dipantau tersendiri</h2><p class="finding-number">${n(r.refrigerants)} <small>t CO₂e · ${leaks===null?'tahun awal':change(leaks)}</small></p><p>${r.year===2025?'Dua kenaikan berurutan: 137,20 pada 2023, 249,99 pada 2024, dan 278,68 pada 2025.':`Refrigeran menyumbang ${n(r.refrigerants/r.scope1*100,1)}% dari Scope 1 yang dilaporkan.`}</p><p><strong>Tindak lanjut.</strong> Tinjau log isi ulang, jenis refrigeran, kebocoran dan perubahan jumlah peralatan. Data emisi saja belum membuktikan penyebab kenaikan.</p>${source(r,r.detailPage??r.page,r.detailPdf??r.pdfPage)}</div></article><article><span>03</span><div><h2>Scope 3 tidak membentuk seri lima tahun</h2><p class="finding-number">1 <small>dari 5 tahun memiliki angka pada dataset</small></p><p>2021 melaporkan 2.843.661 t CO₂e. Angka tidak tercantum di tabel emisi 2022 yang diekstrak; 2023–2025 menyatakan pendataan/perhitungan masih berlangsung.</p><p><strong>Implikasi.</strong> Jangan menjumlahkan Scope 3 tahun 2021 dengan operasi tahun ${r.year}, atau menyajikan penurunan ke nol. Bangun inventaris baru dengan batas dan metode yang terdokumentasi.</p>${source(reports[0])} · ${source(reports[4])}</div></article></div><section class="report-alerts"><div><span class="section-label">PERLU DITINJAU</span><h2>Red flags</h2></div><ul><li><strong>Celah Scope 3.</strong> Tidak ada angka terbaru yang dapat dipakai untuk menghitung total jejak karbon 2025.</li><li><strong>Perubahan batas 2025.</strong> Gudang bertambah dari 3 ke 11; periode es krim hanya Januari–November. Perbandingan belum like-for-like.</li><li><strong>Kenaikan refrigeran.</strong> Dua tahun berturut-turut pada 2024 dan 2025, meski subtotal operasional turun.</li><li><strong>Basis listrik.</strong> Tanda “–” dan nol pada tabel lain perlu dibaca bersama narasi I-REC. Jangan substitusi ke kalkulasi location-based.</li></ul></section>`;}
function plan(state){const r=current(state),p=reportScenario(r.year,state.reportFuel,state.reportLeaks);return head(state,'Prioritas pengurangan','Usulan analisis berdasarkan laporan Unilever Indonesia. Pemilik, jadwal dan target perlu disepakati perusahaan.')+`<div class="action-ledger"><article><div class="action-index">01 <span>UTILITIES / ENGINEERING</span></div><h2>Kurangi kebutuhan panas berbahan bakar fosil</h2><p>Gas dan light fuel menyumbang ${n(r.fuel/r.scope1*100,1)}% Scope 1 pada ${r.year}. Evaluasi pemulihan kondensat, efisiensi boiler dan opsi elektrifikasi dengan audit kebutuhan panas per lini.</p><div class="action-measures"><span><strong>Langkah 30 hari</strong>Petakan pemakaian gas, temperatur proses dan jam operasi.</span><span><strong>KPI</strong>GJ bahan bakar per ton produk; t CO₂e dari gas & light fuel.</span><span><strong>Dasar bukti</strong>${source(r,r.detailPage??r.page,r.detailPdf??r.pdfPage)}</span></div></article><article><div class="action-index">02 <span>MAINTENANCE / SHE</span></div><h2>Investigasi kenaikan emisi refrigeran</h2><p>Prioritaskan pemeriksaan aset dengan isi ulang tinggi. Pertimbangkan refrigeran ber-GWP lebih rendah setelah menilai keselamatan, kesesuaian teknis dan biaya.</p><div class="action-measures"><span><strong>Langkah 30 hari</strong>Rekonsiliasi log isi ulang dengan stok dan hasil uji kebocoran.</span><span><strong>KPI</strong>kg refrigeran bocor, jenis/GWP dan t CO₂e; bukan hanya ODP.</span><span><strong>Dasar bukti</strong>137,20 → 249,99 → 278,68 t CO₂e (2023–2025).</span></div></article><article><div class="action-index">03 <span>PROCUREMENT / SUSTAINABILITY</span></div><h2>Bangun kembali inventaris Scope 3</h2><p>Pakai bahan baku dan kemasan sebagai titik awal investigasi berdasarkan data historis 2021. Tinjau relevansi semua kategori; pemeringkatan 2021 belum tentu berlaku untuk portofolio saat ini.</p><div class="action-measures"><span><strong>Langkah 30 hari</strong>Tetapkan batas, pemilik data dan daftar pemasok prioritas.</span><span><strong>KPI</strong>Cakupan data pemasok, kategori dinilai, faktor terdokumentasi.</span><span><strong>Dasar bukti</strong>${source(reports[0])} · ${source(reports[4])}</span></div></article></div><section class="report-simulator"><div><span class="section-label">SIMULASI · BUKAN TARGET RESMI</span><h2>Uji pengurangan pada basis ${r.year}</h2><p>Persentase di bawah adalah asumsi pengguna. Hanya mengubah dua komponen Scope 1. Tidak menghitung Scope 3, manfaat I-REC tambahan, biaya, ataupun penghematan yang sudah dicapai.</p><label for="report-fuel">Pengurangan emisi gas & light fuel <output id="report-fuel-output">${state.reportFuel}%</output></label><input id="report-fuel" type="range" min="0" max="100" step="1" value="${state.reportFuel}"><label for="report-leaks">Pengurangan emisi refrigeran <output id="report-leaks-output">${state.reportLeaks}%</output></label><input id="report-leaks" type="range" min="0" max="100" step="1" value="${state.reportLeaks}"></div><div class="scenario-result"><span>Potensi pengurangan</span><strong id="report-saving">${n(p.avoided)}</strong><span>t CO₂e · asumsi pengguna</span><dl><div><dt>Subtotal awal</dt><dd>${n(p.baseline)}</dd></div><div><dt>Setelah skenario</dt><dd id="report-projected">${n(p.projected)}</dd></div></dl><button class="btn" data-report-action="reset">Reset asumsi</button></div></section>`;}
function method(state){return head(state,'Data & sumber','Ekstraksi manual terverifikasi dari lima laporan resmi. Angka tidak diambil dari dataset demonstrasi.')+table()+`<div class="source-ledger">${reports.map(r=>`<article><div><span class="source-year">${r.year}</span>${source(r,r.page,r.pdfPage,'Buka PDF resmi')}</div><div><h2>Sustainability Report ${r.year}</h2><p>Emisi: hlm. ${r.page}${r.detailPage?'–'+r.detailPage:''} (PDF ${r.pdfPage}${r.detailPdf?'–'+r.detailPdf:''}). Intensitas: hlm. ${r.intensityPage} (PDF ${r.intensityPdf}).</p><p><strong>Scope 3:</strong> ${e(r.scope3Note)}</p><p><strong>Scope 2:</strong> ${e(r.scope2Note)}</p><p><strong>Batas / catatan:</strong> ${e(r.boundary)} ${e(r.caveat)}</p>${r.year===2025?'<p>Subtotal operasi 2025 diambil dari tabel pengurangan emisi hlm. 186 (PDF 188). Basis 2015 berbeda antara tabel utama dan tabel pengurangan; dashboard tidak menghitung ulang klaim penurunan terhadap 2015.</p>':''}</div></article>`).join('')}</div><section class="report-method"><h2>Aturan pembacaan data</h2><ol><li>Setiap tahun memakai angka pada laporan tahun bersangkutan. Ini seri <em>as reported</em>, bukan seri restatement yang dinormalisasi.</li><li>Tanda “–” dipertahankan sebagai nilai kosong. Angka 0 pada tabel sekunder dijelaskan tanpa mengganti tanda tabel utama.</li><li>Scope 3 yang tidak tersedia tidak diinterpolasi dan tidak dianggap nol. Total rantai nilai 2021 adalah 2.864.519,40 t CO₂e; tidak dibandingkan dengan subtotal operasi tahun berikutnya.</li><li>Intensitas memakai kg CO₂e per ton produk dan hanya mencakup manufaktur. Emisi absolut memiliki cakupan organisasi yang lebih luas.</li><li>Perubahan tahunan = (nilai tahun ini − nilai tahun lalu) ÷ nilai tahun lalu × 100. Perubahan bukan bukti sebab-akibat.</li><li>Kalkulator tambahan memakai aktivitas × faktor kg CO₂e/unit ÷ 1.000. Hasilnya adalah skenario internal yang terpisah dari laporan resmi.</li></ol><a href="${reportIndex}" target="_blank" rel="noopener noreferrer">Indeks laporan resmi Unilever Indonesia ↗</a><p class="chart-footnote">Dataset ditinjau 13 Oktober 2026. Tautan membuka PDF resmi; halaman tercetak dan nomor halaman PDF dicatat terpisah. Tidak ada sinkronisasi otomatis: pembaruan memerlukan ekstraksi dan verifikasi ulang.</p></section>`;}
export function renderReports(state,view){return `<div class="reports">${({overview,analytics,insights,plan,method}[view]??overview)(state)}</div>`;}
export function refreshScenario(state){const p=reportScenario(state.reportYear,state.reportFuel,state.reportLeaks);document.querySelector('#report-saving').textContent=n(p.avoided);document.querySelector('#report-projected').textContent=n(p.projected);document.querySelector('#report-fuel-output').textContent=state.reportFuel+'%';document.querySelector('#report-leaks-output').textContent=state.reportLeaks+'%';}
